statechart InstrumentControl {
  region Power {
    state OFF {
      on START [startup_allowed == true] -> ON.IDLE;
      on START [startup_allowed == false] -> OFF;
    }
    state ON {
      state IDLE {
        on SELF_TEST [self_test_passed == true] -> SELF_TEST.PASS;
        on SELF_TEST [self_test_passed == false] -> SELF_TEST.FAIL;
        on CONFIGURE [config_valid == true] -> CONFIGURING;
        on CONFIGURE [config_valid == false] -> CONFIGURING;
        on DYNAMIC_RECONFIG [beam_switch_possible == true] -> DYNAMIC_RECONFIG;
        on DYNAMIC_RECONFIG [beam_switch_possible == false] -> IDLE;
        on RUN [telescope_idle == true] -> RUNNING;
        on RUN [telescope_idle == false] -> IDLE;
        on SHUTDOWN [shutdown_allowed == true] -> SHUTDOWN;
        on SHUTDOWN [shutdown_allowed == false] -> IDLE;
      }
      state RUNNING {
        on STOP -> IDLE;
        on SHUTDOWN [shutdown_allowed == true] -> SHUTDOWN;
        on SHUTDOWN [shutdown_allowed == false] -> RUNNING;
      }
      state SELF_TEST {
        state PASS {
          on COMPLETE -> IDLE;
        }
        state FAIL {
          on RETRY [self_test_passed == true] -> PASS;
          on RETRY [self_test_passed == false] -> FAIL;
          on ABORT -> IDLE;
        }
      }
      state CONFIGURING {
        on COMPLETE -> IDLE;
        on ERROR -> IDLE;
      }
      state DYNAMIC_RECONFIG {
        on COMPLETE -> IDLE;
        on ERROR -> IDLE;
      }
      state SHUTDOWN {
        on COMPLETE -> OFF;
        on ERROR -> OFF;
      }
    }
  }
  region Status {
    state MONITORING {
      on UPDATE [status_known == true] -> MONITORING;
      on UPDATE [status_known == false] -> MONITORING;
    }
  }
}
